export type EntitlementStatus = "enabled" | "revoked";

export interface EntitlementInput {
  id: string;
  product: string;
  units: number;
  intervalSteps: number;
  intervalCount: number;
  lastChargedStep: number | null;
  status: EntitlementStatus;
}

export interface EntitlementView extends EntitlementInput {}

function validate(input: EntitlementInput): void {
  if (typeof input.id !== "string" || input.id.trim().length === 0) {
    throw new Error("id must be non-empty");
  }
  if (typeof input.product !== "string" || input.product.trim().length === 0) {
    throw new Error("product must be non-empty");
  }
  if (!Number.isInteger(input.units) || input.units < 0) {
    throw new Error("units must be a non-negative integer");
  }
  if (!Number.isInteger(input.intervalSteps) || input.intervalSteps <= 0) {
    throw new Error("intervalSteps must be a positive integer");
  }
  if (!Number.isInteger(input.intervalCount) || input.intervalCount <= 0) {
    throw new Error("intervalCount must be a positive integer");
  }
  if (input.lastChargedStep !== null &&
      (!Number.isInteger(input.lastChargedStep) || input.lastChargedStep < 0)) {
    throw new Error("lastChargedStep must be null or a non-negative integer");
  }
  if (input.status !== "enabled" && input.status !== "revoked") {
    throw new Error("invalid status");
  }
}

function copy(input: EntitlementInput): EntitlementView {
  return { ...input };
}

export class EntitlementRegistry {
  private readonly entries = new Map<string, EntitlementView>();

  constructor(initial: readonly EntitlementInput[] = []) {
    for (const input of initial) {
      this.add(input);
    }
  }

  add(input: EntitlementInput): void {
    validate(input);
    if (this.entries.has(input.id)) {
      throw new Error("duplicate id");
    }
    this.entries.set(input.id, copy(input));
  }

  list(status?: EntitlementStatus): EntitlementView[] {
    if (status !== undefined && status !== "enabled" && status !== "revoked") {
      throw new Error("invalid status");
    }
    return Array.from(this.entries.values())
      .filter((entry) => status === undefined || entry.status === status)
      .sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0)
      .map(copy);
  }

  revoke(id: string): boolean {
    const entry = this.entries.get(id);
    if (entry === undefined || entry.status === "revoked") {
      return false;
    }
    entry.status = "revoked";
    return true;
  }
}

