import { EntitlementRegistry, EntitlementInput } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, message: string): void {
  let didThrow = false;
  try { fn(); } catch (error) { didThrow = error instanceof Error; }
  assert(didThrow, message);
}

const registry = new EntitlementRegistry();
equal(registry.list().length, 0, "omitted initial collection is valid");

const initial: EntitlementInput = {
  id: " b ", product: " Product ", units: 0, intervalSteps: 1,
  intervalCount: 2, lastChargedStep: null, status: "enabled"
};
const populated = new EntitlementRegistry([
  initial,
  { id: "A", product: "alpha", units: 4, intervalSteps: 3, intervalCount: 1, lastChargedStep: 7, status: "revoked" },
  { id: "a", product: "lower", units: 1, intervalSteps: 2, intervalCount: 3, lastChargedStep: 0, status: "enabled" }
]);
initial.product = "mutated";
initial.units = 99;
const ordered = populated.list();
equal(ordered.map(entry => entry.id).join("|"), " b |A|a", "entries use ordinary ascending ID order");
equal(ordered[0].product, " Product ", "constructor snapshots entries");
equal(ordered[0].units, 0, "constructor state is independent");
equal(populated.list("enabled").map(entry => entry.id).join("|"), " b |a", "status filter works");
equal(populated.list("revoked").length, 1, "revoked filter works");

ordered[0].product = "changed through view";
ordered[0].status = "revoked";
equal(populated.list()[0].product, " Product ", "list returns fresh objects");
equal(populated.list()[0].status, "enabled", "view mutation cannot change status");

const added: EntitlementInput = { id: "z", product: "zed", units: 2, intervalSteps: 5, intervalCount: 6, lastChargedStep: 8, status: "enabled" };
populated.add(added);
added.product = "later";
equal(populated.list().find(entry => entry.id === "z")?.product, "zed", "add snapshots its input");
equal(populated.revoke("z"), true, "enabled entry is revoked");
equal(populated.list().find(entry => entry.id === "z")?.status, "revoked", "revocation changes state");
equal(populated.revoke("z"), false, "already revoked entry is unchanged");
equal(populated.revoke("missing"), false, "unknown entry is unchanged");

throws(() => populated.add({ ...added }), "duplicate IDs are rejected");
const base = { id: "valid", product: "product", units: 0, intervalSteps: 1, intervalCount: 1, lastChargedStep: null, status: "enabled" as const };
throws(() => new EntitlementRegistry([{ ...base, id: "   " }]), "blank ID is rejected");
throws(() => new EntitlementRegistry([{ ...base, product: "\t\n" }]), "blank product is rejected");
for (const units of [-1, 1.5, NaN, Infinity]) throws(() => new EntitlementRegistry([{ ...base, units }]), "invalid units are rejected");
for (const intervalSteps of [0, -1, 1.5, NaN, Infinity]) throws(() => new EntitlementRegistry([{ ...base, intervalSteps }]), "invalid intervalSteps are rejected");
for (const intervalCount of [0, -1, 2.5, NaN, Infinity]) throws(() => new EntitlementRegistry([{ ...base, intervalCount }]), "invalid intervalCount is rejected");
for (const lastChargedStep of [-1, 1.5, NaN, Infinity]) throws(() => new EntitlementRegistry([{ ...base, lastChargedStep }]), "invalid lastChargedStep is rejected");
throws(() => new EntitlementRegistry([base, { ...base }]), "constructor rejects duplicate IDs");

